<?php require __DIR__.'/_nav.php';use OCP\IURLGenerator;$url=\OC::$server->get(IURLGenerator::class);?>
<div id="app-content"><div class="erp-page"><h1>Aufträge</h1><p class="erp-sub">Aus angenommenen Angeboten erzeugte Aufträge.</p><div class="erp-table"><table><thead><tr><th>Nummer</th><th>Datum</th><th>Kunde</th><th>Titel</th><th>Status</th><th>Netto</th><th>Brutto</th></tr></thead><tbody><?php foreach($_['orders'] as $o):?><tr><td><a href="<?php p($url->linkToRoute('reinhardterp.business.orderDetail',['id'=>$o['id']]));?>"><strong><?php p($o['order_no']);?></strong></a></td><td><?php p(date('d.m.Y',strtotime($o['order_date'])));?></td><td><?php p($o['customer_name']);?></td><td><?php p($o['title']);?></td><td><span class="erp-badge"><?php p($o['status']);?></span></td><td><?php p(number_format((float)$o['net_amount'],2,',','.').' €');?></td><td><?php p(number_format((float)$o['gross_amount'],2,',','.').' €');?></td></tr><?php endforeach;?></tbody></table></div></div></div>